// DealFit vendoring — build-time only (Mobile Phase 0, 2026-11-22).
//
// Regenerates docs/vendor/ so the served app loads NO runtime JavaScript or
// font from a third-party CDN:
//   • supabase-js-2.112.3.js — the exact pinned Supabase SDK (formerly
//     https://esm.sh/@supabase/supabase-js@2.112.3) bundled with its transitive
//     code into one browser ES module (esbuild, platform=browser).
//   • fonts/*.woff2 + fonts.css — Syne (variable, 400–800) and DM Mono (400, 500):
//     the families the stylesheets actually use, with the same weights and unicode
//     subsets the pages previously requested from fonts.googleapis.com. (shared.html
//     also requested Outfit, which no stylesheet ever referenced — not vendored.)
//   • LICENSES/ — every bundled package's license text.
//   • VENDOR_MANIFEST.json — versions, npm integrity, output SHA-256s.
//
// Regenerate:  cd tools/vendor && npm ci && npm run vendor
// Verify:      cd tools/vendor && npm ci && npm run verify   (rebuilds in a temp
//              dir and fails unless every output byte-matches docs/vendor/)
// Exact versions come from package.json + package-lock.json; never a range.
import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync, copyFileSync, rmSync, readdirSync, statSync, mkdtempSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const NM = join(HERE, 'node_modules');
const VERIFY = process.argv.includes('--verify');
const OUT = VERIFY ? mkdtempSync(join(tmpdir(), 'dealfit-vendor-')) : join(ROOT, 'docs', 'vendor');

const SUPABASE_VERSION = '2.112.3';
const SDK_FILE = `supabase-js-${SUPABASE_VERSION}.js`;
const pkg = (name) => JSON.parse(readFileSync(join(NM, name, 'package.json'), 'utf8'));
const lock = JSON.parse(readFileSync(join(HERE, 'package-lock.json'), 'utf8'));
const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

if (pkg('@supabase/supabase-js').version !== SUPABASE_VERSION) throw new Error('installed supabase-js is not ' + SUPABASE_VERSION + ' — run npm ci');

rmSync(OUT, { recursive: true, force: true });
mkdirSync(join(OUT, 'fonts'), { recursive: true });
mkdirSync(join(OUT, 'LICENSES'), { recursive: true });

// 1. Supabase SDK → one self-contained browser ES module.
const result = await build({
  stdin: { contents: "export * from '@supabase/supabase-js';", resolveDir: HERE, sourcefile: 'supabase-entry.js', loader: 'js' },
  bundle: true, format: 'esm', platform: 'browser', target: 'es2020',
  minify: true, legalComments: 'eof', write: false, logLevel: 'silent',
  banner: { js: `/* @supabase/supabase-js ${SUPABASE_VERSION} — vendored by tools/vendor/build.mjs (esbuild ${pkg('esbuild').version}); licenses in ./LICENSES/ */` },
});
const sdk = result.outputFiles[0].contents;
if (/\bfrom\s*["']https?:|import\(\s*["']https?:/.test(Buffer.from(sdk).toString('utf8'))) throw new Error('bundle still contains a remote import');
writeFileSync(join(OUT, SDK_FILE), sdk);

// 2. Fonts: copy only the files the pages use, and write fonts.css under the
//    family names the stylesheets already reference ('Syne', 'DM Mono').
const FONTS = [
  { family: 'Syne', pkg: '@fontsource-variable/syne', weight: '400 800', files: ['syne-greek-wght-normal', 'syne-latin-ext-wght-normal', 'syne-latin-wght-normal'], format: 'woff2-variations' },
  { family: 'DM Mono', pkg: '@fontsource/dm-mono', weight: null, files: ['dm-mono-latin-ext-400-normal', 'dm-mono-latin-400-normal', 'dm-mono-latin-ext-500-normal', 'dm-mono-latin-500-normal'], format: 'woff2' },
];
let css = `/* Self-hosted fonts — generated by tools/vendor/build.mjs from @fontsource packages (SIL OFL 1.1; see ./LICENSES/). Do not edit by hand. */\n`;
for (const f of FONTS) {
  const srcCss = readFileSync(join(NM, f.pkg, 'index.css'), 'utf8') + (f.weight ? '' : readFileSync(join(NM, f.pkg, '500.css'), 'utf8'));
  for (const file of f.files) {
    const block = srcCss.split('@font-face').find(b => b.includes(`./files/${file}.woff2`));
    if (!block) throw new Error('no @font-face for ' + file);
    const range = (block.match(/unicode-range:\s*([^;]+);/) || [])[1];
    const weight = f.weight || (block.match(/font-weight:\s*(\d+);/) || [])[1];
    copyFileSync(join(NM, f.pkg, 'files', file + '.woff2'), join(OUT, 'fonts', file + '.woff2'));
    css += `@font-face{font-family:'${f.family}';font-style:normal;font-display:swap;font-weight:${weight};src:url(./fonts/${file}.woff2) format('${f.format}');unicode-range:${range}}\n`;
  }
}
writeFileSync(join(OUT, 'fonts.css'), css);

// 3. Licenses of everything that ships.
const LICENSED = [
  ['@supabase/supabase-js', 'LICENSE'], ['@supabase/auth-js', 'LICENSE'], ['@supabase/functions-js', 'LICENSE'],
  ['@supabase/postgrest-js', 'LICENSE'], ['@supabase/realtime-js', 'LICENSE'], ['@supabase/storage-js', 'LICENSE'],
  ['@supabase/phoenix', 'LICENSE.md'], ['tslib', 'LICENSE.txt'], ['iceberg-js', 'LICENSE'],
  ['@fontsource-variable/syne', 'LICENSE'], ['@fontsource/dm-mono', 'LICENSE'],
];
for (const [name, file] of LICENSED) copyFileSync(join(NM, name, file), join(OUT, 'LICENSES', name.replace('/', '__') + '__' + file));

// 4. Manifest (provenance + output hashes). No timestamps, so rebuilds are byte-stable.
const files = [];
const walk = (d) => { for (const n of readdirSync(d).sort()) { const p = join(d, n); if (statSync(p).isDirectory()) walk(p); else if (n !== 'VENDOR_MANIFEST.json') files.push(p); } };
walk(OUT);
const manifest = {
  generator: 'tools/vendor/build.mjs', regenerate: 'cd tools/vendor && npm ci && npm run vendor', verify: 'cd tools/vendor && npm ci && npm run verify',
  esbuild: pkg('esbuild').version,
  packages: LICENSED.map(([name]) => ({ name, version: pkg(name).version, license: pkg(name).license, integrity: (lock.packages['node_modules/' + name] || {}).integrity || null })),
  replaces: { 'https://esm.sh/@supabase/supabase-js@2.112.3': 'vendor/' + SDK_FILE, 'https://fonts.googleapis.com/css2 (Syne 400-800, DM Mono 400/500; Outfit was requested by shared.html but never used)': 'vendor/fonts.css' },
  outputs: Object.fromEntries(files.map(p => [relative(OUT, p).split('\\').join('/'), sha256(readFileSync(p))])),
};
writeFileSync(join(OUT, 'VENDOR_MANIFEST.json'), JSON.stringify(manifest, null, 2) + '\n');

if (VERIFY) {
  const live = join(ROOT, 'docs', 'vendor');
  const bad = [];
  const all = [...files.map(p => relative(OUT, p)), 'VENDOR_MANIFEST.json'];
  for (const r of all) { let a = null; try { a = readFileSync(join(live, r)); } catch {} if (!a || sha256(a) !== sha256(readFileSync(join(OUT, r)))) bad.push(r); }
  const extra = []; const walk2 = (d, b = '') => { for (const n of readdirSync(d)) { const p = join(d, n); if (statSync(p).isDirectory()) walk2(p, join(b, n)); else if (!all.includes(join(b, n))) extra.push(join(b, n)); } };
  walk2(live);
  rmSync(OUT, { recursive: true, force: true });
  if (bad.length || extra.length) { console.error('vendor verify FAILED — differs: ' + bad.join(', ') + (extra.length ? ' — unexpected: ' + extra.join(', ') : '')); process.exit(1); }
  console.log(`vendor verify OK — ${all.length} files byte-identical to docs/vendor/`);
} else {
  console.log(`vendored ${files.length + 1} files into docs/vendor/ (SDK ${sdk.length} B)`);
}
